SELECT lop.hk_order_product AS sales_line_hk, lop.hk_order AS order_hk, lop.hk_product AS product_hk, loc.hk_customer AS customer_hk, loe.hk_employee AS employee_hk, ho.order_key, lop.order_line_number, so.order_date, cast(date_format(so.order_date, 'yyyyMMdd') AS INT) AS order_date_key, so.order_status, so.currency_code, sol.quantity, sol.unit_price, sol.discount_amount, bv.gross_amount, bv.net_amount_calc AS net_amount, bv.discount_rate, bv.lead_time_days, bv.is_cancelled, sol.ship_date, sol.delivery_date, cast(date_format(sol.ship_date, 'yyyyMMdd') AS INT) AS ship_date_key, cast(date_format(sol.delivery_date, 'yyyyMMdd') AS INT) AS delivery_date_key, sol.load_date AS valid_from, coalesce(sol.load_end_date, timestamp'9999-12-31 23:59:59') AS valid_to, sol.is_current, sol.record_source FROM {processing}.raw_vault.lnk_order_product lop JOIN {processing}.raw_vault.hub_order ho ON ho.hk_order = lop.hk_order JOIN {processing}.raw_vault.sat_order_line sol ON sol.hk_order_product = lop.hk_order_product LEFT JOIN {processing}.business_vault.sat_order_line_bv bv ON bv.hk_order_product = lop.hk_order_product AND bv.is_current LEFT JOIN {processing}.raw_vault.sat_order so ON so.hk_order = lop.hk_order AND so.is_current LEFT JOIN {processing}.raw_vault.lnk_order_customer loc ON loc.hk_order = lop.hk_order LEFT JOIN {processing}.raw_vault.lnk_order_employee loe ON loe.hk_order = lop.hk_order
